namespace sv_2d13d825c8744a00a3f966130f4b4365.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// In Blazor Server, "scoped" means one instance per circuit (per user tab).
/// </summary>
public class ThemeService
{
    public Theme CurrentTheme { get; private set; } = Theme.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChanged;

    public void SetTheme(Theme theme)
    {
        if (CurrentTheme == theme) return;
        CurrentTheme = theme;
        OnChanged?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChanged?.Invoke();
    }

    public void SetPreferences(Theme theme, string accentColor)
    {
        var changed = CurrentTheme != theme || AccentColor != accentColor;
        CurrentTheme = theme;
        AccentColor = accentColor;
        if (changed) OnChanged?.Invoke();
    }
}

@* 
    This component is rendered with @rendermode InteractiveServer in the layout,
    making it part of the circuit even though MainLayout itself is static.
    This is the key pattern for reactive state in a static layout.
*@
@using sv_2d13d825c8744a00a3f966130f4b4365.Services
@implements IDisposable
@inject ThemeService ThemeService

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme">
    @GetThemeIcon() @ThemeService.CurrentTheme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetThemeIcon() => ThemeService.CurrentTheme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleThemeChanged;
    }
}

@using sv_2d13d825c8744a00a3f966130f4b4365.Services
@implements IDisposable
@inject ThemeService ThemeService

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        style="border-color: @ThemeService.AccentColor;">
    @GetThemeIcon() Toggle Theme
</button>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += HandleThemeChanged;
    }

    private void CycleTheme()
    {
        var next = ThemeService.CurrentTheme switch
        {
            Theme.Light => Theme.Dark,
            Theme.Dark => Theme.System,
            _ => Theme.Light
        };
        ThemeService.SetTheme(next);
    }

    private string GetThemeIcon() => ThemeService.CurrentTheme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        _ => "💻"
    };

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleThemeChanged;
    }
}

