@page "/settings"
@rendermode InteractiveServer
@using sv_2d13d825c8744a00a3f966130f4b4365.Services
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="card p-4" style="max-width: 500px; border-color: @ThemeService.AccentColor;">
    <div class="mb-3">
        <label class="form-label">Theme</label>
        <select class="form-select" @bind="selectedTheme">
            <option value="@Theme.Light">Light</option>
            <option value="@Theme.Dark">Dark</option>
            <option value="@Theme.System">System</option>
        </select>
    </div>

    <div class="mb-3">
        <label class="form-label">Accent Color</label>
        <input type="color" class="form-control form-control-color" @bind="selectedColor" />
    </div>

    <button class="btn btn-primary" style="background-color: @ThemeService.AccentColor; border-color: @ThemeService.AccentColor;"
            @onclick="SavePreferences">
        Save Preferences
    </button>

    <div class="mt-3 text-muted">
        <small>Current: @ThemeService.CurrentTheme | Accent: @ThemeService.AccentColor</small>
    </div>
</div>

@code {
    private Theme selectedTheme;
    private string selectedColor = "#0d6efd";

    protected override void OnInitialized()
    {
        selectedTheme = ThemeService.CurrentTheme;
        selectedColor = ThemeService.AccentColor;
        ThemeService.OnChanged += HandleThemeChanged;
    }

    private void SavePreferences()
    {
        ThemeService.SetPreferences(selectedTheme, selectedColor);
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(() =>
        {
            selectedTheme = ThemeService.CurrentTheme;
            selectedColor = ThemeService.AccentColor;
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleThemeChanged;
    }
}

